from 写入第二遍 import add
add('12_002',2,'16:9，贴斜面低位广角；起幅是近侧触地亮痕，镜头向上摇到青单脚触面、另一腿屈起，继续带出悬在她上方的断烟囱；摄影机维持同一倾斜角，不翻转地平线。','青手掌离开接触面，身体从后翻转回面向武士，落下的一脚短促蹬住斜面，另一腿屈起收近腰侧；她朝断烟囱所在的高度弹起，双臂分开平衡，长发比头部更晚甩到上方，脚边灰尘留下一个向外张开的短痕。','近处灰褐粗糙屋面向下退出，上摇途中露出米灰烟囱断块、深灰碎屑和铅蓝天空。','烟囱后侧开阔天空的冷白柔光从人物侧上方落下；屋面反光较弱。','鞋底短蹬、砂粒散开，发束裂风和碎砖下落声交叠。',phase='process',node={'青.接触':'脚蹬屋面后离开','青.阶段':'转身回正接近断烟囱'},meaning='保留脚触面、屈腿、发束扬起及断烟囱的上下关系；手触屋面的借力与后续掌推烟囱是不同接触。')
add('12_003',3.5,'16:9，斜向中近景，断烟囱从左上压入，青在右中部拧身，双手收在胸前。镜头跟随胸胯扭转向她正前侧移少许，落幅保留烟囱边缘、脸和准备推出的手掌。','青收住刚才的惊慌，眉头压紧、牙关露出，转脸看向画外武士；腰胯先向后蓄住，胸肩跟着拧开，左臂收近肋侧，右手由半握松成张开的掌形，掌根朝向身旁的断烟囱。说到句尾，她的眼睛从武士移到将要接触的砖面，后脚向斜面压实。','米灰烟囱砖面占左上角，青身后是被屋脊遮去下半的冷灰天空。','烟囱后侧天空给较亮冷白柔光，砖块投下的软影压到画面左上。','衣料扭转擦响，脚下砂粒一小串滚落，近处短而用力的呼气。',japanese=['淑女に向かって…！'],tone='恼怒地压出前半句，话意暂未收束。',phase='preparation',kind='mixed',node={'青.阶段':'拧身准备掌推断烟囱','青.接触':'脚下短促受力'},pcard={'opening':'惊慌转为不服输的回击。','beats':['露齿压眉、看向武士','胸胯拧开，拳松为掌，注意转到砖面'],'coupling':'口头反击与具体发力准备同一方向推进。','landing':'右掌已对准砖面，力量尚未推出。'})
add('12_004',1,'16:9，掌根与断烟囱侧面极近景；砖面从左上斜压下来，青的腕臂由画面右侧伸入，掌根和弯曲的指端同时可见。','青的右掌贴住断烟囱侧缘，指端沿边自然弯曲，掌根压实后肘部开始伸直；砖屑在掌根附近轻抖，整块烟囱向武士方向开始移动，手与砖面之间仍有明确接触。','米灰砖面与深灰砂浆裂缝占大部，砖体外侧是浅冷灰天空。','开阔天空冷白柔光从砖体后上侧照来，接触缝内较暗。','贴掌一声干实轻响，砖缝砂粒细响，随后是向前起动的低风声。',phase='contact',node={'青.接触':'右掌贴断烟囱','烟囱.状态':'被掌推开始向武士移动'},meaning='手掌贴住已切断烟囱并前推，不是抓起石块投掷。右手选择为本次动作连续性的导演设计，不伪称源裁切已独立证实手别。',update={'first_pass':{'viewed':True,'resolution':'720p','session_date':'2026-10-25','observation':'一只手的掌根贴住砖体边缘，指端顺边弯曲，腕臂从画面右侧伸入；砖缝与接触拟声可见。手别在裁切中不独立确认。','initial_action_understanding':'按用户解释：手掌贴住被斩断的烟囱，前推砸向武士。'}})
